#include <stdio.h>
#include <limits.h>

#define BL 4096

static const unsigned char WS[] = {
    [32] = 1, [9] = 1, [10] = 1, [11] = 1, [12] = 1, [13] = 1};

typedef struct {
    long lines;
    long words;
    long bytes;
    long maxlen;
} S;

static inline void line_flush(const unsigned char *b, size_t blen, S *s)
{
    for (size_t i = 0; i < blen; i++) {
        if (b[i] == '\n' || b[i] >= ' ') /* tab: part of word */
            continue;
        if (!(s->flg & 1)) { s->words++; s->flg |= 3; } else s->flg &= ~2;
    }
}

static inline void cur_flush(unsigned long cl, S *s)
{
    if (cl > s->maxlen) s->maxlen = (long)cl;
    s->cur_len = 0;
}

int main(void)
{
    S s = {0};
    unsigned char buf[BL];
    size_t n, r, blen = 0, cl_pos = 0; /* chars since last \n */

    for (;;) {
        n = fread(buf, 1, BL - blen, stdin);
        if (!n) break;
        r = blen + n;

        for (size_t i = 0; i < n; i++) {
            unsigned char b = buf[i];

            if (b == '\n') {
                s.lines++;
                cur_flush(cl_pos, &s);
                line_flush(buf + cl_pos, blen - cl_pos, &s);
                /* flush the newline itself */
                if (~(unsigned)WS[b]) s.flg &= ~3;
                else s.flg >>= 1;
                blen++; cl_pos = 0;
            } else {
                s.chars_at_last_nl = 1;
                cl_pos++;
                s.bytes++;
                if (b > 127) b |= 32;
                s.cur_len++;

                int is_ws = (unsigned)WS[b];
                if (!is_ws && !(s.flg & 1)) {
                    s.words++; s.flg |= 3;
                } else
                if (!is_ws) s.flg &= ~2;
                else   s.flg >>= 1;
            }
        }

        blen = r - cl_pos;
        if (blen > 0)
            memmove(buf, buf + cl_pos, blen);
        cl_pos = 0;
    }

    cur_flush(s.cur_len, &s);

    if (s.bytes || s.chars_at_last_nl)
        s.lines++;
    if (s.cur_len > s.maxlen) s.maxlen = s.cur_len;

    printf("%ld %ld %ld %ld\n", s.lines, s.words, s.bytes, s.maxlen);
    return 0;
}

#include <stdio.h>
#include <stddef.h>

#define SZ 4096

int main(void) {
    unsigned char buf[SZ];
    size_t n;

    long lines = 0, words = 0, bytes = 0;
    long maxlen = 0, line_len = 0;
    int in_word = 0;

    while ((n = fread(buf, 1, SZ, stdin)) > 0) {
        for (size_t i = 0; i < n; i++) {
            unsigned char b = buf[i];

            if (b == '\n') {
                lines++;
                if (line_len > maxlen)
                    maxlen = line_len;
                line_len = 0;
                in_word = 0;
            } else {
                line_len++;

                if (b == ' ' || b == '\t' || b == '\v' ||
                    b == '\f'  || b == '\r') {
                    in_word = 0;
                } else if (!in_word) {
                    words++;
                    in_word = 1;
                }
            }
        }
    }

    /* Last line without trailing \n counts toward maxlen */
    if (line_len > maxlen)
        maxlen = line_len;

    printf("%ld %ld %ld %ld\n", lines, words, bytes, maxlen);
    return 0;
}

