    while ((n = fread(buf, 1, SZ, stdin)) > 0) {
        for (size_t i = 0; i < n; i++) {
            unsigned char b = buf[i];

            bytes++;                /* count every byte */

            if (b == '\n') {
                lines++;
                if (line_len > maxlen)
                    maxlen = line_len;
                line_len = 0;
            } else {
                int is_ws;
                switch (b) {
                case ' ': case '\t': case '\v':
