                if (!is_ws && !in_word) {
                    words++;
                    in_word = 1;
                } else if (is_ws) {
                    in_word = 0;
                }
                line_len++;           /* \r is ordinary for maxlen */
            }
        }
    }
    if (line_len > maxlen)
        maxlen = line_len;          /* un-terminated last line */

    printf("%ld %ld %ld %ld\n", lines, words, bytes, maxlen);
    return 0;
}

